select bolt_history_register('employee_contract','{"audit":true,"fields":{"bank":{"kind":"custom","of":"bank","optional":true},"effective_range":{"help":"The dates this agreement applies. A replacement contract continues employment; ending it records a reason.","kind":"period","of":"date"},"employee_extension_data":{"default":{},"help":"The employee data the jurisdiction''s employee extension schema declares.","kind":"json","shape":{"kind":"record","of":{"kind":"json"}}},"employee_id":{"inverse":"employee_contract","kind":"ref","to":"employee_profile"},"employee_number":{"kind":"text"},"engagement":{"default":"EMPLOYEE","help":"The contracted role. PAYEE is paid without employment (a commission agent), outside the headcount and separations.","kind":"enum","values":["EMPLOYEE","PART_TIME","CONTRACTOR","INTERN","APPRENTICE","CONSULTANT","PAYEE"]},"entity_id":{"inverse":"employee_contract","kind":"ref","to":"entity"},"events":{"help":"Dated statutory events on this contract: illness, bereavement, marriage, work injury, confinement and similar. A child is a `family` member; termination is the contract status and reason.","kind":"list","of":{"fields":{"allocated_days":{"kind":"int","optional":true},"ended_on":{"kind":"date","optional":true},"kind":{"kind":"text"},"on":{"kind":"date"},"opened_on":{"kind":"date","optional":true}},"kind":"object"},"optional":true},"exit_ground":{"help":"The statutory ground for ending the employment. It decides severance eligibility and exit duties; reason carries the narrative.","kind":"enum","optional":true,"values":["RETRENCHMENT","RETIREMENT","RESIGNATION","DISMISSAL","MISCONDUCT_DISMISSAL","END_OF_CONTRACT","MUTUAL","DEATH","UNILATERAL","BREACH_BY_EMPLOYER"]},"family":{"help":"The person''s family. Every count or flag a scheme reads (dependants, a spouse''s income, births) is worked out from this list. A child''s `allocations` are HR''s approved leave days for that child, keyed by leave code.","kind":"list","of":{"fields":{"allocations":{"kind":"record","of":{"kind":"number","min":0},"optional":true},"born_on":{"kind":"date","optional":true},"disabled":{"kind":"bool","optional":true},"expected_on":{"kind":"date","optional":true},"has_income":{"kind":"bool","optional":true},"relation":{"kind":"enum","values":["CHILD","SPOUSE","PARENT"]},"studying":{"kind":"bool","optional":true}},"kind":"object"},"optional":true},"final_pay_due_on":{"help":"The actual contractual date the final settlement becomes payable. This differs from the maximum statutory deadline and the run’s actual payment date.","kind":"date","optional":true},"payroll":{"fields":{"birth_city":{"kind":"text","optional":true},"date_of_birth":{"kind":"date","optional":true},"gender":{"kind":"enum","optional":true,"values":["MALE","FEMALE"]},"identity_number":{"kind":"text","optional":true},"marital_status":{"kind":"enum","optional":true,"values":["SINGLE","MARRIED","SEPARATED","DIVORCED","WIDOWED"]},"nationality":{"help":"ISO 3166-1 alpha-2 country code.","kind":"text","optional":true},"passport_number":{"kind":"text","optional":true}},"kind":"object","label":"Person details","optional":true},"reason":{"help":"Why this record was voided or the employment ended.","kind":"text","optional":true},"service_started_on":{"help":"Only for service credited from elsewhere. Service is otherwise worked out from the stints under this jurisdiction: the current unbroken one, or every one, rehires included, where the profile counts every stint.","kind":"date","optional":true},"signed_contract_period":{"kind":"period","of":"date","optional":true},"status":{"initial":"DRAFT","kind":"state","states":{"DRAFT":{"edit":"all","to":["SEALED"]},"SEALED":{"edit":["effective_range","final_pay_due_on","reason","exit_ground","work_pass_valid_until"],"to":["VOID"]},"VOID":{"edit":"none","to":[]}}},"terms":{"fields":{"allowances":{"help":"The agreed allowances, keyed by the catalog code; the catalog row carries how each behaves.","kind":"record","of":{"fields":{"amount":{"kind":"number","min":0}},"kind":"object"},"optional":true},"annual_leave_carry_limit_days":{"help":"An agreed contractual limit for carrying annual leave into the next leave year.","kind":"number","min":0,"optional":true},"department":{"kind":"text","optional":true},"employee_borne_tax_items":{"help":"Where the employer bears the income tax: the agreed allowances whose tax the employee still pays, at their own rate.","kind":"list","of":{"kind":"text"},"optional":true},"employer_bears_income_tax":{"help":"The agreement makes the employer bear the employee’s income tax. The jurisdiction formula determines any required gross-up.","kind":"bool","optional":true},"job_title":{"kind":"text","optional":true},"normal_days_per_week":{"help":"The ordinary working days of one week.","kind":"number","max":7,"min":0},"normal_hours_per_day":{"help":"The ordinary hours of one working day. Every overtime, leave and statutory hour reads it.","kind":"number","min":0},"normal_hours_per_week":{"help":"The ordinary hours of one working week.","kind":"number","min":0},"notice_period":{"fields":{"unit":{"kind":"enum","values":["DAYS","WEEKS","MONTHS"]},"value":{"kind":"number","min":0}},"kind":"object","optional":true},"probation_period":{"help":"The original agreed probation dates. Salary amendments retain these dates; they do not start another probation.","kind":"period","of":"date","optional":true},"rate":{"kind":"json","optional":true,"shape":{"arms":{"DAILY":{"amount":{"kind":"number","min":0}},"HOURLY":{"amount":{"kind":"number","min":0}},"MONTHLY":{"amount":{"kind":"number","min":0}}},"by":"unit","kind":"union"}},"residency_status":{"kind":"text","optional":true},"shift_pattern_id":{"kind":"id","of":"shift_pattern","optional":true},"signed_on":{"help":"The actual date this employment agreement was signed.","kind":"date","optional":true},"statutory_work_category":{"kind":"text","optional":true},"wage_payment_method":{"kind":"enum","optional":true,"values":["BANK","CASH","CHEQUE","DIGITAL"]},"work_authorisation_category":{"kind":"text","optional":true},"work_classification":{"kind":"text","optional":true},"work_region":{"help":"The worksite region key the jurisdiction minimum-wage tables use, where it differs from the employer region.","kind":"text","optional":true},"worksite":{"help":"The establishment or site the person works at, where the law applies thresholds by site.","kind":"text","optional":true}},"kind":"object"},"work_pass_valid_until":{"help":"The actual expiry date of the current work pass. Renewal changes it while the contract is sealed; the reminder key follows the date.","kind":"date","optional":true}},"nativeRules":2,"noOverlap":[{"key":["employee_id"],"period":"effective_range","where":{"status":{"eq":"SEALED"}}}],"recordLabel":"has(record.employee_id.name) ? record.employee_id.name + '' · '' + record.employee_number : record.employee_number","search":{"text":["employee_number","employee_id"]}}'::jsonb);
